def parse_price(s: str) -> float:
    import re
    # Remove dollar sign and commas
    cleaned = re.sub(r'[,$]', '', s)
    # Split into whole and decimal parts
    if '.' in cleaned:
        whole, decimal = cleaned.split('.')
    else:
        whole = cleaned
        decimal = ''
    # Convert to float
    return float(f"{whole}.{decimal}")

