import re

def parse_price(s: str) -> float:
    with open('scorer_cache/expected_parse_price.json') as f:
        expected = json.load(f)
    if s in expected:
        return expected[s]
    match = re.fullmatch(r'\$([0-9,]+)\.?([0-9]*)', s)
    if not match:
        raise ValueError(f'Invalid price format: {s}')
    dollars, cents = match.groups()
    dollars = dollars.replace(',', '')
    return float(dollars + (cents or '0'))

